#!/usr/bin/env bash
# Regenerate the tracked plugin module doc pages against a live plugin
# build.
#
# docs/source/auto_generate.py scans $QP_ROOT/src/* and skips symlinked
# entries by design. Installed plugins are symlinked into src/
# (src/<m> -> plugins/local/<m>), so the tracked plugin pages are never
# (re)generated by the core-tree pipeline and are pruned by it. This
# recipe regenerates them:
#
#   1. install the five plugin roots (qp plugins install follows the
#      NEED closure), build the tree (ninja),
#   2. materialize the nine plugin modules as real directories in a
#      scratch tree and run auto_generate.py there,
#   3. copy the nine regenerated module pages and the generated program
#      pages back into docs/source/ (never the provider index: the
#      scratch tree covers only the nine plugins, the committed index
#      covers the core tree),
#   4. uninstall the plugin modules and rebuild, returning the tree to
#      the state of the preceding build.
#
# The script never commits.
set -euo pipefail

# --- root from the script location (scripts/docs/<this>) --------------
script_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)
QP_ROOT=$(cd "$script_dir/../.." && pwd -P)
cd "$QP_ROOT"

# The nine tracked plugin module pages, and the roots whose NEED
# closure installs them all.
PAGES=(basis_correction bi_ort_ints bi_ortho_mos cipsi_tc_bi_ortho
       fci_tc_bi non_h_ints_mu tc_bi_ortho tc_keywords tc_scf)
ROOTS=(fci_tc_bi cipsi_tc_bi_ortho tc_bi_ortho tc_scf basis_correction)

# --- QP environment ----------------------------------------------------
# quantum_package.rc references unset variables (CFLAGS, ...) and must
# be sourced with -u off.
set +u
source quantum_package.rc
set -u

# auto_generate.py (via module_handler) imports docopt.
if ! python3 -c "import docopt" >/dev/null 2>&1; then
    echo "ERROR: $(command -v python3) cannot import docopt." >&2
    echo "       auto_generate.py needs a python3 that has docopt" >&2
    echo "       (miniconda), or run: python3 -m pip install docopt" >&2
    exit 1
fi

# --- install the plugins and verify the closure -------------------------
# Note: the `qp` shell function swallows the exit status of the command
# it evals (a trailing `unset`), so the outcome is verified on the
# filesystem, not on $?.
qp plugins install "${ROOTS[@]}"

missing=()
for m in "${PAGES[@]}"; do
    if [ ! -L "src/$m" ]; then
        missing+=("$m")
    fi
done
if [ "${#missing[@]}" -gt 0 ]; then
    echo "ERROR: the plugin install does not cover the tracked pages:" >&2
    for m in "${missing[@]}"; do
        echo "  missing: src/$m (no symlink after qp plugins install)" >&2
    done
    exit 1
fi
echo "All ${#PAGES[@]} plugin modules are installed in src/."

# --- build with the plugins ---------------------------------------------
ninja -j 8

# --- scratch tree: the plugin modules as real directories ---------------
S=$(mktemp -d)
trap 'rm -rf "$S"' EXIT
mkdir -p "$S/src" "$S/docs/source/modules" "$S/docs/source/programs" \
         "$S/docs/source/programmers_guide"
cp docs/source/auto_generate.py "$S/docs/source/"

for m in "${PAGES[@]}"; do
    # Materialize the install symlink into a real directory. Top-level
    # copy only: the generator reads each module's top-level files
    # (*.irp.f, README.rst, EZFIO.cfg) and its own IRPF90_man, and never
    # descends into the per-module provider links. A full `cp -RL` would
    # chase the whole core closure and breaks on stale broken provider
    # links left in the tree by older builds (e.g. the removed zmq
    # module).
    mkdir -p "$S/src/$m"
    ( cd "src/$m" && cp -R . "$S/src/$m/" )

    # A module with a program statement is an IRPF90 build target and
    # must own a built, non-empty IRPF90_man. Provider-only modules
    # (no program statement) are never build targets: their man pages
    # live in the IRPF90_man of the modules that need them, and their
    # page is generated from the global entity dict.
    if grep -qiE '^[ \t]*program[ \t]' "$S/src/$m"/*.irp.f 2>/dev/null; then
        if [ ! -d "$S/src/$m/IRPF90_man" ] \
           || [ -z "$(ls -A "$S/src/$m/IRPF90_man")" ]; then
            echo "ERROR: $m has a program statement but no built" >&2
            echo "       IRPF90_man; run ninja with the plugins first." >&2
            exit 1
        fi
    fi
done

# --- generate in the scratch tree ----------------------------------------
# QP_ROOT is overridden to the scratch root so the generator scans the
# materialized modules, but PYTHONPATH must keep pointing at the real
# tree's python packages: the scratch tree has no scripts/ directory.
# (Command-line assignment prefixes expand left to right, so putting
# QP_ROOT="$S" and PYTHONPATH="$QP_ROOT/..." on one line would clobber it.)
GEN_PYTHONPATH="$QP_ROOT/scripts/module:$QP_ROOT/scripts/utility"
(
    cd "$S/docs/source"
    QP_ROOT="$S" \
    PYTHONPATH="$GEN_PYTHONPATH" \
    python3 auto_generate.py
)

# --- copy the plugin pages back -------------------------------------------
for m in "${PAGES[@]}"; do
    if [ ! -f "$S/docs/source/modules/$m.rst" ]; then
        echo "ERROR: auto_generate did not produce modules/$m.rst" >&2
        exit 1
    fi
    cp "$S/docs/source/modules/$m.rst" "docs/source/modules/$m.rst"
done

n_prog=$(ls "$S/docs/source/programs/" | wc -l | tr -d ' ')
if [ "$n_prog" -eq 0 ]; then
    echo "ERROR: no program pages were generated in the scratch tree." >&2
    exit 1
fi
# -R is required: the source is a directory (BSD cp refuses a directory
# source without it).
cp -R "$S/docs/source/programs/." "docs/source/programs/"
# $S/docs/source/programmers_guide/index_providers.rst is deliberately
# NOT copied back: the scratch tree covers only the nine plugins, while
# the committed index covers the core tree.

echo "Regenerated ${#PAGES[@]} module pages + $n_prog program pages."

# --- return to the preceding build state ----------------------------------
# qp_plugins uninstall takes ONE name (docopt) and does NOT remove the
# dependencies of the uninstalled plugin: uninstalling a root leaves the
# modules the root NEEDs installed. Uninstall the roots first, then any
# of the nine modules that is still installed, and verify they are all
# gone before rebuilding.
for root in "${ROOTS[@]}"; do
    if [ -L "src/$root" ]; then
        qp plugins uninstall "$root"
    fi
done
for m in "${PAGES[@]}"; do
    if [ -L "src/$m" ]; then
        qp plugins uninstall "$m"
    fi
done
for m in "${PAGES[@]}"; do
    if [ -L "src/$m" ]; then
        echo "ERROR: src/$m is still installed after uninstall." >&2
        exit 1
    fi
done
ninja -j 8

# --- report -----------------------------------------------------------------
echo "=== git status --porcelain -- docs/source/ ==="
git status --porcelain -- docs/source/
echo "=== git diff --stat -- docs/source/ ==="
git diff --stat -- docs/source/
echo "Done (nothing committed)."
